// Deriva el país real: usa la columna country si la hoja la trae,
// si no, cae al prefijo del teléfono (mismo criterio que WF10/WF11/WF13).
function detectCountry(r) {
  const c = String(r.country || '').trim().toLowerCase();
  if (c === 'india' || c === 'nepal' || c === 'mexico') return c;
  const p = String(r.phone || '').replace(/[^0-9]/g, '');
  if (p.startsWith('977')) return 'nepal';
  if (p.startsWith('91'))  return 'india';
  if (p.startsWith('52'))  return 'mexico';
  return 'india'; // último fallback conservador
}

